import type {ContextProvenance} from './inventoryContextAI';
import type {RiskBasis,DemoReviewSummary,DemoTimestamp,Decoded} from './inventoryDemoReorder';
export type PurchaseLineInput={productId:string;quantity:number;unitCost:number};
export type PurchaseCreateInput={reference:string;supplierId:string;expectedDate:string;items:PurchaseLineInput[]};
export type PurchaseActionInput={id:string;version:number;notes:string}&({step:'Approve'|'Reject'|'Issue'|'Cancel'}|{step:'Resubmit';supplierId:string;expectedDate:string;items:PurchaseLineInput[]}|{step:'Receive';quantities:number[];receiptReference:string});
export type LegacyCreateInput={operationId:string;kind:'Create';requirementId:string;expectedRequirementVersion:2;acceptedEventId:string;purchase:PurchaseCreateInput};
export type ActionInput={operationId:string;kind:'Action';purchase:PurchaseActionInput};
export type CreateInput=Omit<LegacyCreateInput,'purchase'>&{contractVersion:2;purchase:Omit<PurchaseCreateInput,'reference'>};
export type ProcurementInput=CreateInput|LegacyCreateInput|ActionInput;
export type CreateDraft=Omit<CreateInput,'operationId'>;export type ActionDraft=Omit<ActionInput,'operationId'>;
export type ProcurementOutcome={state:'Completed'|'Cancelled';operationId:string;kind:'Create'|'Action';purchaseOrderId:string|null;eventId:string|null;status:string|null;version:number|null;replayed:boolean;reference?:string|null};
export type DemoProcurementSource={version:1;policyVersion:'demo-procurement-1.0';requirementId:string;alertId:string;experimentId:string;review:DemoReviewSummary;basis:RiskBasis;provenance:ContextProvenance};
export type DemoProcurementLink={version:1;ownerId:string;requirementId:string;purchaseOrderId:string;sourceSha256:string;createdBy:string;createdAt:DemoTimestamp;dataOrigin:'demonstration-test'};
export type ExpectedReplenishment={version:1;ownerId:string;purchaseOrderId:string;requirementId:string;source:DemoProcurementSource;sourceSha256:string;product:{productId:string;name:string;sku:string};supplier:{supplierId:string;name:string;contact:string};orderedQuantity:number;receivedQuantity:number;outstandingQuantity:number;expectedDate:string;orderVersion:number;state:'Expected'|'PartReceived'|'Received';createdAt:DemoTimestamp;updatedAt:DemoTimestamp;dataOrigin:'demonstration-test'};
export const DEMO_PROCUREMENT_POLICY:'demo-procurement-1.0';
export function validateDemoProcurementInput(value:unknown):ProcurementInput;
export function validateDemoProcurementOutcome(value:unknown,input:ProcurementInput):ProcurementOutcome;
export function decodeDemoProcurementSource(value:unknown):Promise<DemoProcurementSource>;
export function demoProcurementSourceSha256(value:DemoProcurementSource):Promise<string>;
export function verifyAcceptedDemoProcurementSource(value:{id:string;alert:unknown;requirement:unknown;experiment:unknown;event:unknown}):Promise<DemoProcurementSource>;
export function decodeDemoProcurementLink(value:unknown,id:string):Decoded<DemoProcurementLink,'link'>;
export function decodeExpectedReplenishment(value:unknown,id:string):Promise<Decoded<ExpectedReplenishment,'expected'>>;
